return [
  { json: { catKey: '2309150002', catLabel: '서울 자체', listBase: 'https://youth.seoul.go.kr/infoData/plcyInfo/ctList.do?key=2309150002&tabKind=002', listSuffix: '&orderBy=regYmd+desc&blueWorksYn=N&sw=', detailBase: 'https://youth.seoul.go.kr/infoData/plcyInfo/view.do', detailSuffix: '&tab=001&key=2309150002&tabKind=002' } },
  { json: { catKey: '2309160001', catLabel: '중앙정부/타지역', listBase: 'https://youth.seoul.go.kr/infoData/youthPlcyInfo/list.do?key=2309160001', listSuffix: '', detailBase: 'https://youth.seoul.go.kr/infoData/youthPlcyInfo/view.do', detailSuffix: '&key=2309160001' } }
];

const html = $input.first().json.data;
const pageIndex = $('페이지 초기화').first().json.pageIndex 
  || $('다음 페이지 이동').first().json.pageIndex
  || 1;

// goView('V202600006') / goView('20260528005400113227') 패턴에서 plcyBizId 추출 (양 카테고리)
const regex = /goView\('([A-Za-z0-9]+)'\)/g;
const ids = [];
let match;
while ((match = regex.exec(html)) !== null) {
  ids.push(match[1]);
}

// 마지막 페이지 번호 추출: fn_egov_link_page(67) 에서 최대값
const pageRegex = /fn_egov_link_page\((\d+)\)/g;
let maxPage = 1;
let pageMatch;
while ((pageMatch = pageRegex.exec(html)) !== null) {
  const p = parseInt(pageMatch[1]);
  if (p > maxPage) maxPage = p;
}

// 총 건수 추출: (총 <strong class="fc-blue">332</strong>건)
const totalMatch = html.match(/총\s*<strong[^>]*>(\d+)<\/strong>\s*건/);
const totalCount = totalMatch ? parseInt(totalMatch[1]) : 0;

const items = ids.map(id => ({
  json: {
    plcyBizId: id,
    currentPage: pageIndex,
    lastPage: maxPage,
    totalCount: totalCount
  }
}));

if (items.length === 0) {
  return [{ json: { empty: true, currentPage: pageIndex, lastPage: maxPage } }];
}

return items;

const html = $input.first().json.data;
const plcyBizId = $('정책별 순차 처리').first().json.plcyBizId;
const cat = $('카테고리별 순차 처리').first().json;

// Helper: th 텍스트로 인접 td 내용 추출 (정제 보강)
// 동기화: __fixtures__/youth-seoul-parse-body/parse-body.mjs 와 동일 알고리즘
function extractByTh(thText) {
  const escapedTh = thText.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const regex = new RegExp(
    '<th[^>]*>' + escapedTh + '</th>\\s*<td[^>]*>([\\s\\S]*?)</td>',
    'i'
  );
  const match = html.match(regex);
  if (!match) return '';
  return match[1]
    .replace(/<!--[\s\S]*?-->/g, '')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/?[a-zA-Z][^>]*>/g, '')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\t/g, '')
    .replace(/^[  ]*-{3,}[  ]*$/gm, '')
    .replace(/-{4,}>/g, '')
    .replace(/\n\s*\n/g, '\n')
    .trim();
}

const REF_SECTIONS = ['관련 사이트', '신청 사이트', '참고 사이트 Ⅰ', '참고 사이트 Ⅱ'];
function extractRefUrls() {
  const urls = []; const seen = new Set();
  for (const th of REF_SECTIONS) {
    const escTh = th.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const re = new RegExp('<th[^>]*>' + escTh + '</th>\\s*<td[^>]*>([\\s\\S]*?)</td>', 'i');
    const m = html.match(re);
    if (!m) continue;
    const hrefRe = /href="(https?:\/\/[^"]+)"/gi;
    let hm;
    while ((hm = hrefRe.exec(m[1])) !== null) {
      const u = hm[1];
      if (seen.has(u)) continue;
      seen.add(u);
      urls.push(u);
    }
  }
  return urls.slice(0, 3);
}

const ATTACHMENT_EXT_PATTERN = /\.(pdf|hwp|hwpx|docx?|xlsx?|zip)(\?|$|#)/i;
function extractSelfAttachments() {
  const out = []; const seen = new Set();
  const linkRe = /<a[^>]*href="([^"]+)"[^>]*>([\s\S]*?)<\/a>/gi;
  let lm;
  while ((lm = linkRe.exec(html)) !== null) {
    const href = lm[1];
    if (!ATTACHMENT_EXT_PATTERN.test(href)) continue;
    const abs = /^https?:\/\//i.test(href)
      ? href
      : 'https://youth.seoul.go.kr' + (href.startsWith('/') ? href : '/' + href);
    if (seen.has(abs)) continue;
    seen.add(abs);
    const text = lm[2].replace(/<[^>]+>/g, '').trim().slice(0, 200);
    out.push({ name: text || abs.split('/').pop(), url: abs });
  }
  return out;
}

// 제목 추출: <strong class="title">...</strong>
const titleMatch = html.match(/<strong\s+class="title">([^<]+)<\/strong>/);
const title = titleMatch ? titleMatch[1].trim() : '';

const category = extractByTh('정책 유형');
const introduction = extractByTh('정책 소개');
const supportContent = extractByTh('지원 내용');

const periodText = extractByTh('사업신청기간');
let applyStart = null;
let applyEnd = null;
if (periodText) {
  const dateRegex = /(\d{4})\.\s*(\d{1,2})\.\s*(\d{1,2})/g;
  const dates = [];
  let dm;
  while ((dm = dateRegex.exec(periodText)) !== null) {
    const y = dm[1];
    const m = dm[2].padStart(2, '0');
    const d = dm[3].padStart(2, '0');
    dates.push(`${y}-${m}-${d}`);
  }
  if (dates.length >= 1) applyStart = dates[0];
  if (dates.length >= 2) applyEnd = dates[1];
}

const ageInfo = extractByTh('연령');
const procedure = extractByTh('신청절차');
const documents = extractByTh('제출서류');

const bodyParts = [];
if (introduction) bodyParts.push('사업개요: ' + introduction);
if (ageInfo) bodyParts.push('지원대상: ' + ageInfo);
if (supportContent) bodyParts.push('지원내용: ' + supportContent);
if (procedure) bodyParts.push('신청방법: ' + procedure);
if (documents) bodyParts.push('제출서류: ' + documents);

const body = bodyParts.join('\n');

const sourceUrl = cat.detailBase + '?plcyBizId=' + plcyBizId + cat.detailSuffix;

const result = {
  source: {
    url: sourceUrl,
    type: 'YOUTH_SEOUL',
    fetchedAt: new Date().toISOString().replace('Z', '')
  },
  rawData: {
    title: title,
    body: body,
    category: category || '복지',
    region: '서울',
    applyStart: applyStart,
    applyEnd: applyEnd,
    _refUrls: extractRefUrls(),
    _selfAttachments: extractSelfAttachments()
  }
};

return [{ json: result }];

// 현재 배치의 정책 정보에서 페이지 정보 가져오기
const items = $('plcyBizId 추출').all();
const firstItem = items[0]?.json || {};
const currentPage = firstItem.currentPage || 1;
const lastPage = firstItem.lastPage || 1;

if (currentPage < lastPage) {
  // 다음 페이지로 이동
  return [{ json: { pageIndex: currentPage + 1, hasNext: true } }];
} else {
  // 모든 페이지 처리 완료
  return [{ json: { pageIndex: currentPage, hasNext: false } }];
}

const items = $('plcyBizId 추출').all();
const firstItem = items[0]?.json || {};
const totalCount = firstItem.totalCount || 0;
const lastPage = firstItem.lastPage || 0;

return [{
  json: {
    message: '크롤링 완료',
    totalPolicies: totalCount,
    totalPages: lastPage,
    completedAt: new Date().toISOString()
  }
}];
